INSERT INTO `academy_book` (`id`, `title`, `author`, `description`, `cover`, `embed_url`, `source_url`, `created_at`, `category_id`) VALUES
('abb4d616-ede0-444c-bf32-1227fb7cc207', 'Handbook FinTec untuk UMKM', 'FinTech Indonesia', 'Fintech merupakan singkatan dari financial technology atau teknologi finansial dan dapat diartikan sebagai inovasi layanan keuangan berbasis teknologi. Fintech memberikan kemudahan bagi konsumen dalam menggunakan/ memanfaatkan berbagai layanan jasa keuangan secara digital, seperti: pembayaran, pinjaman, investasi, dan asuransi. Dengan menggunakan fintech, konsumen dapat melakukan transaksi pembayaran tanpa harus bertatap muka, memperoleh pinjaman tanpa harus mengunjungi kantor cabang bank, memilih, dan mengetahui produk keuangan yang palling sesuai dengan kebutuhan kita, berinvestasi secara mudah serta memperoleh nasihat perencanaan keuangan. Di sisi lain, fintech juga berperan penting dalam membantu lembaga keuangan untuk melakukan penilaian/ pemeringkatan kredit serta proses mengenal konsumen secara elektronik sehingga memungkinkan UMKM dalam memperoleh pinjaman atau layanan keuangan lainnya.', 'books/covers/Handbook_FinTec_untuk_UMKM_20260126102546.png', 'https://drive.google.com/file/d/1TOiGr9sdvlAdPYOryG6fEBfba2ILF4N8/preview', 'https://drive.google.com/file/d/1TOiGr9sdvlAdPYOryG6fEBfba2ILF4N8/preview', '2026-01-26 10:25:46.103614', 3),
('e7fdb46c-543a-4f8b-a095-48c90e435f49', 'Fintech Revolutionuniversal Inclusion In The New Financial Ecosystem', 'Sofie Blakstad, Robert Allen', 'This book is about the future of finance, but it’s also about its immediate past, and the things many people, including us, have done and are doing to make finance fairer and more inclusive. It’s about the opportunities that are now emerging for the billions of people who lack access to traditional financial services, to participate and thrive in the new financial ecosystem.', 'books/covers/Fintech_Revolutionuniversal_Inclusion_In_The_New_Financial_Ecosystem_20260126101940.png', 'https://drive.google.com/file/d/1mqyblCQCBNMu1Nan_GRMmA5Lb4f0I-9H/preview', 'https://drive.google.com/file/d/1mqyblCQCBNMu1Nan_GRMmA5Lb4f0I-9H/preview', '2026-01-26 10:19:40.883512', 3),
('47dc53cb-b8b6-4266-8f8b-4c15b2b445e8', 'Introduction to Python Programming', 'OpenStax, Rice University', 'Introduction to Python Programming is licensed under a Creative Commons Attribution 4.0 International (CC BY) license, which means that you can distribute, remix, and build upon the content, as long as you provide attribution to OpenStax and its content contributors. Because our books are openly licensed, you are free to use the entire book or select only the sections that are most relevant to the needs of your course. Feel free to remix the content by assigning your students certain chapters and sections in your syllabus, in the order that you prefer. You can even provide a direct link in your syllabus to the sections in the web view of your book. Instructors also have the option of creating a customized version of their OpenStax book. Visit the Instructor Resources section of your book page on OpenStax.org for more information.', 'books/covers/Introduction_to_Python_Programming_20260125132327.png', 'https://drive.google.com/file/d/1pL4wyXMxg2CS4lphwzWbOC3Q-Kxi0WIP/preview', 'https://drive.google.com/file/d/1pL4wyXMxg2CS4lphwzWbOC3Q-Kxi0WIP/view', '2026-01-25 13:23:27.952758', 2),
('4169ac6a-3efa-40f8-af2a-4d48a8279c07', 'Pemograman Python untuk Data Science', 'Syamsu Alam', 'Pada dasarnya, modul ini untuk memandu proses pembelajaran individu dan kelompok dalam hal penerapan bahasa pemrograman dalam analisis data dan machine learning. Modul ini akan memandu peserta untuk dapat melakukan praktik mandiri dengan memecahkan kasus (case method) dan pembelajaran berbasis proyek (Project Based Learning). Pada studi kasus dan proyek dalam buku ini disertai sintaks yang memudahkan mahasiswa melakukan aktivitas proyeknya.', 'books/covers/Pemograman_Python_untuk_Data_Science_20260125132933.png', 'https://drive.google.com/file/d/1ZefDqtXn1Y6T_1XG8VTDL0cJXmDDDXnG/preview', 'https://drive.google.com/file/d/1ZefDqtXn1Y6T_1XG8VTDL0cJXmDDDXnG/view?usp=sharing', '2026-01-25 13:29:33.932749', 2),
('295dc723-4c0f-4be2-a3f4-7796859a6a25', 'Eloquent JavaScript: A Modern Introduction to Programming', 'Marijn Haverbeke', 'This is a book about getting computers to do what you want them to\r\ndo. Computers are about as common as screwdrivers today, but they\r\ncontain a lot more hidden complexity and thus are harder to operate and understand. To many, they remain alien, slightly threatening things.', 'books/covers/Eloquent_JavaScript_A_Modern_Introduction_to_Programming_20260201143425.jpg', 'https://drive.google.com/file/d/1slM9VKHJKSRXSYZ65JRW2Ym2KEDs-yma/preview', 'https://drive.google.com/file/d/1slM9VKHJKSRXSYZ65JRW2Ym2KEDs-yma/preview', '2026-02-01 14:34:25.215266', 4),
('781dbcf5-653d-472a-bb68-dd222e54a30a', 'Beginning JavaScript 5th Edition', 'Jeremy McPeak, Paul Wilton', 'First and forem ost , I want to thank God for the blessings he has bestowed upon me, and thank you, dear reader, for without you this book would not be possible. Also, a huge thank you goes to my wife and family for putting up with me as I spent my available weekend free-time updating this book. \r\n\r\nWriting and producing a book requires a lot of people, and I know I cannot name everyone who has had a hand in this project. But a very big thank you goes to Jim Minatel and Robert Elliott for green-lighting this project. Thank you Kelly Talbot for keeping me on track and putting up with me. To the editing team, thank you for making my text look good. And to Russ Mullen, thanks for keeping me honest.', 'books/covers/Beginning_JavaScript_5th_Edition_20260201142819.jpeg', 'https://drive.google.com/file/d/1aSnWXMmnS_lBpWJ4uMOg-scPKFOmxHXB/preview', 'https://drive.google.com/file/d/1aSnWXMmnS_lBpWJ4uMOg-scPKFOmxHXB/preview', '2026-02-01 14:28:19.845348', 4),
('f8db4791-4c4a-42c9-a657-f799ff78ea90', 'Macro Economics - Ninth Edition', 'N. Gregory Mankiw', 'Macroeconomists share a common body of knowledge, but they do not all have the same perspective on how that knowledge is best taught. Let me begin this new edition by recapping my objectives, which together define this book’s approach to the field.', 'books/covers/Macro_Economics_-_Ninth_Edition_20260202032654.jpeg', 'https://drive.google.com/file/d/1ZwLIaVcpTIqMxzu6RMHU9uo_SeVLnBX5/preview', 'https://drive.google.com/file/d/1ZwLIaVcpTIqMxzu6RMHU9uo_SeVLnBX5/preview', '2026-02-02 03:26:54.523389', 1),
('c275cf5f-9851-4f03-a761-fd3f4e043141', 'The Javascript Handbook', 'Flavio C', 'JavaScript is one of the most popular programming languages in the world, and now widely used also outside of the browser. The rise of Node.js in the last few years unlocked backend development, once the domain of Java, Ruby, Python, PHP, and more traditional server-side languages. Learn all about it!', 'books/covers/The_Javascript_Handbook_20260201143706.jpeg', 'https://drive.google.com/file/d/1XA7AmRB5PKGpWqmNjqSm_PjUntOqVDuf/preview', 'https://drive.google.com/file/d/1XA7AmRB5PKGpWqmNjqSm_PjUntOqVDuf/preview', '2026-02-01 14:37:06.495106', 4);
