INSERT INTO `academy_courseassignment` (`id`, `title`, `description`, `file_instruction`, `due_date`, `max_score`, `allow_late_submission`, `created_at`, `updated_at`, `agenda_id`, `assignment_type`, `is_published`) VALUES
(1, 'Algoritma, Pseudocode, dan Flowchart', 'Buatkan Algoritma, Pseudocode, serta flowchart dari pernyataan berikut ini:\r\n\r\nMenentukan apakah seorang mendapatkan diskon berdasarkan total belanja.\r\nKetentuan:\r\n\r\nJika total belanja ? Rp[...] ? Diskon [...] %\r\nJika total belanja < Rp[1000.000] ? Tidak ada diskon\r\n\r\nNilai total belanja merupakan: akumulasi total belanja mahasiswa tersebut dalam 1 bulan..\r\nNilai Diskon merupakan: tanggal lahir dari mahasiswa tersebut..', '', '2026-02-04 15:59:00.000000', 100, 0, '2026-01-21 03:57:11.429326', '2026-02-01 06:48:27.174163', 3, 'individual', 1),
(2, 'Live Coding', 'Silahkan diunggah, riwayat coding menggunakan python..', '', '2026-02-06 04:30:00.000000', 100, 0, '2026-02-06 02:59:02.320897', '2026-02-06 02:59:02.320921', 4, 'individual', 1);
